public sealed class CloudApi : IDisposable {
 public const string Cn="https://aiot-api-cn.anker.com.cn",Eu="https://ankerpower-api-eu.anker.com",Us="https://ankerpower-api.anker.com";
 readonly HttpClient http=new(new HttpClientHandler{AllowAutoRedirect=false,UseCookies=false}){Timeout=TimeSpan.FromSeconds(30)};
 public Authentication? Auth {get;private set;}
 internal CloudApi(HttpClient client,Authentication auth){http.Dispose();http=client;Auth=auth;}
 public CloudApi(){try{var file=Path.Combine(Store.Root,"credentials.bin");if(File.Exists(file)){var data=ProtectedData.Unprotect(File.ReadAllBytes(file),null,DataProtectionScope.CurrentUser);Auth=JsonSerializer.Deserialize<Authentication>(data,Store.Json);CryptographicOperations.ZeroMemory(data);if(Auth?.Expires<=DateTimeOffset.UtcNow.AddSeconds(60))Logout();}}catch{Auth=null;}}
 public void Logout(){Auth=null;string p=Path.Combine(Store.Root,"credentials.bin");if(File.Exists(p))File.Delete(p);}
 public static string Server(string c)=>c=="CN"?Cn:new[]{"AR","AU","BR","CA","MX","NZ","US"}.Contains(c)?Us:Eu;
 static string Gmt(){var t=TimeZoneInfo.Local.GetUtcOffset(DateTime.Now);return "GMT"+(t.Ticks<0?"-":"+")+t.Duration().ToString(@"hh\:mm");}
 async Task<JsonNode> Post(string server,string path,JsonNode body,string country,Authentication? auth=null,Dictionary<string,string>? extra=null,CancellationToken ct=default){if(!new[]{Cn,Eu,Us}.Contains(server)||path.Contains("..")||path.Contains("://")||path.StartsWith('/'))throw new InvalidOperationException("无效的 API 地址");
  using var req=new HttpRequestMessage(HttpMethod.Post,server+"/"+path){Content=new StringContent(body.ToJsonString(),Encoding.UTF8,"application/json")};
  var heads=new Dictionary<string,string>{{"model-type",country=="CN"?"PHONE":"DESKTOP"},{"app-name","anker_power"},{"os-type","android"},{"country",country},{"timezone",Gmt()}};
  if(country=="CN"){heads["app-version"]="3.23.0";heads["language"]="zh-Hans";heads["x-app-key"]="CN";heads["x-auth-ts"]=DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString();}
  if(auth!=null){if(auth.Expires<=DateTimeOffset.UtcNow.AddSeconds(60))throw new IOException("Anker 登录已过期，请重新登录。");heads["x-auth-token"]=auth.Token;heads["gtoken"]=Convert.ToHexString(MD5.HashData(Encoding.UTF8.GetBytes(auth.UserId))).ToLowerInvariant();}
  if(extra!=null)foreach(var kv in extra)heads[kv.Key]=kv.Value;foreach(var kv in heads)req.Headers.TryAddWithoutValidation(kv.Key,kv.Value);
  using var res=await http.SendAsync(req,ct);if(res.StatusCode is HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden){Logout();throw new IOException("Anker 登录已过期，请重新登录。");}res.EnsureSuccessStatusCode();
  var root=JsonNode.Parse(await res.Content.ReadAsStringAsync(ct))??throw new IOException("Anker 返回空响应");int code=(int?)root["code"]??-1;if(code!=0){if(code is 26084 or 401 or 403)Logout();throw new IOException("Anker 请求失败，代码 "+code+(path.StartsWith("passport/phone")?"":": "+(string?)root["msg"]));}return root["data"]?.DeepClone()??new JsonObject();
 }
 public Task<JsonNode> Post(string path,JsonNode body,Dictionary<string,string>? extra=null,CancellationToken ct=default){var a=Auth??throw new IOException("请先登录 Anker 账号");return Post(a.Server,path,body,a.Country,a,extra,ct);}
 public Task<JsonNode> Sms(string phone){if(!Regex.IsMatch(phone,@"^1\d{10}$"))throw new ArgumentException("请输入 11 位中国大陆手机号");return Post(Cn,"passport/phone_verification_code",new JsonObject{["phone_number"]=phone,["kind"]="login"},"CN");}
 public async Task Login(string account,string secret,string country){country=country.Trim().ToUpperInvariant();string server=Server(country);using var own=ECDiffieHellman.Create(ECCurve.NamedCurves.nistP256);var q=own.ExportParameters(false).Q;string pub="04"+Convert.ToHexString(q.X!).ToLowerInvariant()+Convert.ToHexString(q.Y!).ToLowerInvariant();JsonObject body;string path;
  if(country=="CN"){if(!Regex.IsMatch(account,@"^1\d{10}$")||!Regex.IsMatch(secret,@"^\d{6}$"))throw new ArgumentException("请输入手机号和 6 位验证码");body=new(){["phone_number"]=account,["verify_code"]=secret,["client_secret_info"]=new JsonObject{["public_key"]=pub}};path="passport/phone_verification_login";}
  else{if(!account.Contains('@')||string.IsNullOrEmpty(secret))throw new ArgumentException("请输入邮箱和密码");var sp=Convert.FromHexString("04c5c00c4f8d1197cc7c3167c52bf7acb054d722f0ef08dcd7e0883236e0d72a3868d9750cb47fa4619248f3d83f0f662671dadc6e2d31c2f41db0161651c7c076");using var peer=ECDiffieHellman.Create(new ECParameters{Curve=ECCurve.NamedCurves.nistP256,Q=new(){X=sp[1..33],Y=sp[33..]}});byte[] k=own.DeriveRawSecretAgreement(peer.PublicKey);using var aes=Aes.Create();aes.Key=k;aes.IV=k[..16];string encrypted=Convert.ToBase64String(aes.EncryptCbc(Encoding.UTF8.GetBytes(secret),k[..16],PaddingMode.PKCS7));CryptographicOperations.ZeroMemory(k);
   body=new(){["ab"]=country,["email"]=account,["password"]=encrypted,["enc"]=0,["time_zone"]=TimeZoneInfo.Local.GetUtcOffset(DateTime.Now).TotalMilliseconds,["transaction"]=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString(),["client_secret_info"]=new JsonObject{["public_key"]=pub}};path="passport/login";}
  var data=await Post(server,path,body,country);
  if(country!="CN"){string? domain=(string?)data["domain"];if(domain!=null){domain=domain.TrimEnd('/').ToLowerInvariant();if(!domain.StartsWith("https://"))domain="https://"+domain;}string? home=new[]{Eu,Us}.Contains(domain)?domain:data["ab_code"] is {} ab&&ab.ToString()!="CN"?Server(ab.ToString()):null;if(home!=null&&home!=server){server=home;data=await Post(server,path,body,country);}}
  string uid=(string?)data["user_id"]??"",token=(string?)data["auth_token"]??"";if(uid.Length==0||token.Length==0)throw new IOException("登录响应缺少账号 ID 或令牌");if(!double.TryParse(data["token_expires_at"]?.ToString(),out var expires))throw new IOException("登录响应缺少有效期");if(expires>1e11)expires/=1000;
  Auth=new(uid,(string?)data["nick_name"]??"",token,DateTimeOffset.FromUnixTimeSeconds((long)expires),country,server);Directory.CreateDirectory(Store.Root);var b=JsonSerializer.SerializeToUtf8Bytes(Auth,Store.Json);try{File.WriteAllBytes(Path.Combine(Store.Root,"credentials.bin"),ProtectedData.Protect(b,null,DataProtectionScope.CurrentUser));}finally{CryptographicOperations.ZeroMemory(b);}
 }
 public async Task<List<CloudDevice>> Devices(CancellationToken ct=default){var d=await Post("power_service/v1/app/get_relate_and_bind_devices",new JsonObject(),ct:ct);var list=d is JsonArray a?a:d["data"] as JsonArray??new JsonArray();return list.Where(n=>n?["product_code"]?.ToString()=="A2345").Select(n=>new CloudDevice(n!["device_sn"]!.ToString(),n["alias_name"]?.ToString()??n["device_name"]?.ToString()??"Anker Prime 250W",n["owner_user_id"]?.ToString(),n["wifi_online"]?.ToString() is "true" or "1")).ToList();}
 public async Task Upload(byte[] jpeg,string serial){var t=await Post("app/cloudstor/get_app_up_token_general",new JsonObject{["file_name"]="cropped_image.jpg",["content_type"]="binary/octet-stream",["file_size"]=jpeg.Length,["disable_ssl"]=false,["type"]=106},new(){{"user_id",Auth!.UserId}});var url=new Uri(t["uptoken"]!.ToString());if(url.Scheme!="https")throw new IOException("上传 URL 无效");using var req=new HttpRequestMessage(HttpMethod.Put,url){Content=new ByteArrayContent(jpeg)};req.Content.Headers.ContentType=new("binary/octet-stream");using var res=await http.SendAsync(req);res.EnsureSuccessStatusCode();await Post("mini_power/v1/app/style/add_manual_clock_screensavers",new JsonObject{["sn"]=serial,["img_url"]=t["key_prefix"]!.ToString(),["hash_code"]=$"0x{Wire.Crc32(jpeg):x8}"});}
 public void Dispose()=>http.Dispose();
}
public sealed class CloudLink : IDisposable {
 readonly object lifecycle=new();bool disposed;
 readonly CloudApi api;NodeTlsStream? ssl;CancellationTokenSource? session;
 readonly SemaphoreSlim sendGate=new(1),commandGate=new(1);TaskCompletionSource<Reply>? awaiting;ushort awaited;
 string topicRoot="",commandTopic="",clientId="",owner="",app="",certificateId="";CloudDevice? target;
 public DeviceState State {get;private set;}=DeviceState.Empty("A2345");public event Action? Changed;public event Action<string>? Error;
 public CloudLink(CloudApi api){this.api=api;System.Net.NetworkInformation.NetworkChange.NetworkAddressChanged+=NetworkChanged;}
 void NetworkChanged(object? sender,EventArgs args){CancellationToken ct;lock(lifecycle){if(disposed||session==null||!State.Connected)return;ct=session.Token;}TransportFailure(ct,"网络适配器发生变化","Anker 云端连接中断");}
 void TransportFailure(CancellationToken ct,string message,string status){lock(lifecycle){if(disposed||ct.IsCancellationRequested||!State.Connected)return;awaiting?.TrySetException(new IOException("MQTT 已断开"));DisposeConnection();State.Status=status;}Error?.Invoke(message);Changed?.Invoke();}
 static byte[] Str(string s){byte[] b=Encoding.UTF8.GetBytes(s);if(b.Length>65535)throw new IOException("MQTT string too long");return new byte[]{(byte)(b.Length>>8),(byte)b.Length}.Concat(b).ToArray();}
 async Task Packet(byte type,byte[] b,CancellationToken ct){await sendGate.WaitAsync(ct);try{if(ssl==null)throw new IOException("云端未连接");var header=new List<byte>{type};int n=b.Length;do{byte x=(byte)(n%128);n/=128;if(n>0)x|=128;header.Add(x);}while(n>0);await ssl.WriteAsync(header.Concat(b).ToArray(),ct);}finally{sendGate.Release();}}
 async Task<(byte,byte[])> Read(CancellationToken ct){var h=new byte[1];await ssl!.ReadExactlyAsync(h,ct);byte first=h[0];int n=0,m=1;for(int i=0;i<4;i++){await ssl.ReadExactlyAsync(h,ct);n+=(h[0]&127)*m;if((h[0]&128)==0){if(n>270336)throw new IOException("MQTT 数据过大");var b=new byte[n];await ssl.ReadExactlyAsync(b,ct);return(first,b);}m*=128;}throw new IOException("MQTT 长度无效");}
 public async Task Connect(CloudDevice dev,CancellationToken cancelConnect=default){CancellationToken ct;CancellationTokenSource own;lock(lifecycle){if(disposed)throw new ObjectDisposedException(nameof(CloudLink));DisposeConnection();target=dev;State=DeviceState.Empty("A2345",dev.Serial);State.Name=dev.Name;State.Status="正在连接 Anker 云端…";session=new();own=session;ct=session.Token;}using var cancel=cancelConnect.Register(()=>{try{own.Cancel();}catch(ObjectDisposedException){}});Changed?.Invoke();
  try{var cr=await api.Post("app/devicemanage/get_user_mqtt_info",new JsonObject(),ct:ct);string host=cr["endpoint_addr"]!.ToString();if(!Regex.IsMatch(host,@"^[A-Za-z0-9.-]+$"))throw new IOException("MQTT 地址无效");app=cr["app_name"]!.ToString();certificateId=cr["certificate_id"]!.ToString();string uid=cr["user_id"]!.ToString();owner=string.IsNullOrEmpty(dev.Owner)?uid:dev.Owner;foreach(var x in new[]{app,dev.Serial})if(!Regex.IsMatch(x,@"^[A-Za-z0-9_-]+$"))throw new IOException("无效的设备身份");
   ct.ThrowIfCancellationRequested();string thingName=cr["thing_name"]!.ToString();clientId="android-"+app+"-"+uid+"-"+certificateId;topicRoot=$"dt/{app}/A2345/{dev.Serial}";commandTopic=$"cmd/{app}/A2345/{dev.Serial}/req";
   State.Status="正在完成云端 TLS 认证…";Changed?.Invoke();
   ssl=await NodeTlsStream.Connect(host,cr["certificate_pem"]!.ToString(),cr["private_key"]!.ToString(),ct);
   cr=null!;State.Status="正在订阅云端设备…";Changed?.Invoke();
   await Packet(0x10,Str("MQTT").Concat(new byte[]{4,2,0,60}).Concat(Str(thingName+"_"+Random.Shared.Next(100000).ToString("D5"))).ToArray(),ct);var(c,b)=await Read(ct).WaitAsync(TimeSpan.FromSeconds(15),ct);if(c!=0x20||b.Length!=2||b[1]!=0)throw new IOException("Anker MQTT 拒绝连接");
   await Packet(0x82,new byte[]{0,1}.Concat(Str(topicRoot+"/#")).Append((byte)0).ToArray(),ct);bool subscribed=false;
   for(int i=0;i<10;i++){var(t,d)=await Read(ct).WaitAsync(TimeSpan.FromSeconds(15),ct);if(t==0x90){if(d.Length!=3||d[0]!=0||d[1]!=1||d[2]!=0)throw new IOException("MQTT 订阅被拒绝");subscribed=true;break;}}
   if(!subscribed)throw new IOException("MQTT 订阅超时");ct.ThrowIfCancellationRequested();State.Connected=true;State.Status="已连接，等待功率数据…";Changed?.Invoke();_=ReceiveLoop(ct);await Publish(0x200,[],ct);await Publish(0x202,[],ct);await Publish(0x20b,[],ct);_=Poll(ct);
  }catch(Exception e){DisposeConnection();string message=e is TimeoutException?"云端连接超时，请检查网络。":e.Message;State.Status="云端连接失败："+message;Error?.Invoke(message);Changed?.Invoke();throw;}
 }
 async Task ReceiveLoop(CancellationToken ct){try{while(!ct.IsCancellationRequested){var(t,b)=await Read(ct);if((t>>4)!=3)continue;if(b.Length<2)throw new IOException("MQTT 无效消息");int n=b[0]<<8|b[1];if(n==0||n+2>b.Length)throw new IOException("MQTT 无效主题");string topic=Encoding.UTF8.GetString(b,2,n);int offset=2+n,qos=(t>>1)&3;if(qos>1)throw new IOException("MQTT QoS 不支持");if(qos==1){if(offset+2>b.Length)throw new IOException("MQTT packet id missing");await Packet(0x40,b[offset..(offset+2)],ct);offset+=2;}
    if(topic!=topicRoot&&!topic.StartsWith(topicRoot+"/",StringComparison.Ordinal))continue;
    try{var f=Wire.Decode(Wire.ExtractCloud(b[offset..]));var r=Wire.CloudFields(f);if(f.Command==awaited){byte? status=f.Payload.Length>0&&f.Payload[0]<0xa0?f.Payload[0]:null;awaiting?.TrySetResult(r with{Status=status});}if(Telemetry.Apply(State,f.Command,r))Changed?.Invoke();}catch(InvalidDataException){}catch(JsonException){}
   }}catch(OperationCanceledException){}catch(Exception e){TransportFailure(ct,e.GetType().Name,"Anker 云端连接中断");}}
 async Task Poll(CancellationToken ct){try{int i=0;while(!ct.IsCancellationRequested){await Task.Delay(10000,ct);await Packet(0xc0,[],ct);await Publish(0x20b,[],ct);if(++i%3==0)await Publish(0x200,[],ct);if(State.Stale){State.Status="等待设备数据，请确认充电器在线";Changed?.Invoke();}}}catch(OperationCanceledException){}catch(Exception e){TransportFailure(ct,e.Message,"Anker 云端连接中断");}}
 async Task Publish(ushort op,IEnumerable<Field> fields,CancellationToken ct,bool longFields=false){if(target==null)throw new IOException("未选择充电器");var payload=JsonSerializer.Serialize(new{device_sn=target.Serial,account_id=owner,data=Convert.ToBase64String(Wire.Cloud(op,fields,longFields:longFields))});var root=new{head=new{version="1.0.0.1",client_id=clientId,sess_id="1234-5678",msg_seq=1,seed=1,timestamp=DateTimeOffset.UtcNow.ToUnixTimeSeconds(),cmd_status=2,cmd=17,sign_code=1,device_pn="A2345",device_sn=target.Serial},payload};await Packet(0x30,Str(commandTopic).Concat(JsonSerializer.SerializeToUtf8Bytes(root)).ToArray(),ct);}
 public async Task Command(ushort op,IEnumerable<Field> fields,bool longFields=false){if(!State.Connected)throw new IOException("云端未连接");var ct=session!.Token;await commandGate.WaitAsync(ct);try{awaited=(ushort)(0xa00|(op&255));awaiting=new(TaskCreationOptions.RunContinuationsAsynchronously);await Publish(op,fields,ct,longFields);var reply=await awaiting.Task.WaitAsync(TimeSpan.FromSeconds(10),ct);if(reply.Status is >0)throw new IOException("设备拒绝命令，状态 "+reply.Status);await Publish(0x200,[],ct);}finally{awaiting=null;commandGate.Release();}}
 void DisposeConnection(){lock(lifecycle){session?.Cancel();session?.Dispose();session=null;awaiting?.TrySetCanceled();ssl?.Dispose();ssl=null;State.Connected=false;}}
 public void Disconnect(){DisposeConnection();State.Status="未连接";}
 public void Dispose(){lock(lifecycle){disposed=true;System.Net.NetworkInformation.NetworkChange.NetworkAddressChanged-=NetworkChanged;DisposeConnection();}}
}
